PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "media" ("id" integer primary key autoincrement not null, "disk" varchar not null default 'public', "directory" varchar not null default 'media', "visibility" varchar not null default 'public', "name" varchar not null, "path" varchar not null, "width" integer, "height" integer, "size" integer, "type" varchar not null default 'image', "ext" varchar not null, "alt" varchar, "title" varchar, "description" text, "caption" text, "exif" text, "curations" text, "created_at" datetime, "updated_at" datetime, "tenant_id" integer);
CREATE TABLE IF NOT EXISTS "pages" ("id" integer primary key autoincrement not null, "title" text not null, "slug" text not null, "view" text not null, "image" text, "content" text, "is_published" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, "controller" varchar, "route_name" varchar, "route_name_detail" varchar);
CREATE TABLE IF NOT EXISTS "locations" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "heading" text, "about_title" text, "about_description" text, "image" text, "address" text, "general_number" varchar, "customer_care" varchar, "link_maps" text, "link_embedded" text, "is_published" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, "index" integer, "cover_image" text, "about_speciality" text not null);
CREATE TABLE IF NOT EXISTS "location_has_specialities" ("id" integer primary key autoincrement not null, "location_id" integer not null, "speciality_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("location_id") references "locations"("id") on delete cascade on update cascade, foreign key("speciality_id") references "specialities"("id") on delete cascade on update cascade);
CREATE TABLE IF NOT EXISTS "coes" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime, "title" text not null, "slug" text not null, "image" text, "content" text);
CREATE TABLE IF NOT EXISTS "services" ("id" integer primary key autoincrement not null, "slug" varchar not null, "title" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "specialities" ("id" integer primary key autoincrement not null, "title" varchar not null, "created_at" datetime, "updated_at" datetime, "slug" text, "image" text, "content" text);
CREATE TABLE IF NOT EXISTS "location_has_coes" ("id" integer primary key autoincrement not null, "location_id" integer not null, "coe_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("location_id") references "locations"("id") on delete cascade on update cascade, foreign key("coe_id") references "coes"("id") on delete cascade on update cascade);
CREATE TABLE IF NOT EXISTS "subservices" ("id" integer primary key autoincrement not null, "service_id" integer, "slug" varchar not null, "title" varchar not null, "content" text, "image" text, "created_at" datetime, "updated_at" datetime, foreign key("service_id") references services("id") on delete cascade on update no action);
CREATE TABLE IF NOT EXISTS "location_has_subservices" ("id" integer primary key autoincrement not null, "location_id" integer not null, "subservice_id" integer not null, "service_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("location_id") references "locations"("id") on delete cascade on update cascade, foreign key("subservice_id") references "subservices"("id") on delete cascade on update cascade, foreign key("service_id") references "services"("id") on delete cascade on update cascade);
CREATE TABLE IF NOT EXISTS "facilities" ("id" integer primary key autoincrement not null, "slug" varchar not null, "title" varchar not null, "content" text, "image" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "location_has_facilities" ("id" integer primary key autoincrement not null, "location_id" integer not null, "facility_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("location_id") references "locations"("id") on delete cascade on update cascade, foreign key("facility_id") references "facilities"("id") on delete cascade on update cascade);
CREATE TABLE IF NOT EXISTS "emergencies" ("id" integer primary key autoincrement not null, "slug" varchar not null, "title" varchar not null, "content" text, "image" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "location_has_emergencies" ("id" integer primary key autoincrement not null, "location_id" integer not null, "emergency_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("location_id") references "locations"("id") on delete cascade on update cascade, foreign key("emergency_id") references "emergencies"("id") on delete cascade on update cascade);
CREATE TABLE IF NOT EXISTS "departments" ("id" integer primary key autoincrement not null, "title" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "career_categories" ("id" integer primary key autoincrement not null, "title" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "careers" ("id" integer primary key autoincrement not null, "career_category_id" integer, "slug" varchar not null, "title" varchar not null, "location_id" integer, "department_id" integer, "qualification" text, "description" text, "created_at" datetime, "updated_at" datetime, foreign key("career_category_id") references "career_categories"("id"), foreign key("location_id") references "locations"("id"), foreign key("department_id") references "departments"("id"));
CREATE TABLE IF NOT EXISTS "location_has_careers" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "news_categories" ("id" integer primary key autoincrement not null, "title" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "news" ("id" integer primary key autoincrement not null, "title" text not null, "slug" text not null, "news_category_id" integer, "image" text, "content" text, "created_at" datetime, "updated_at" datetime, foreign key("news_category_id") references "news_categories"("id") on update cascade);
CREATE TABLE IF NOT EXISTS "testimonies" ("id" integer primary key autoincrement not null, "name" text not null, "title" text not null, "content" text not null, "image" text not null, "video" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "doctors" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "speciality_id" integer, "image" text, "biography" text, "expertise" text, "education" text, "publication" text, "created_at" datetime, "updated_at" datetime, foreign key("speciality_id") references "specialities"("id"));
CREATE TABLE IF NOT EXISTS "doctor_has_locations" ("id" integer primary key autoincrement not null, "doctor_id" integer not null, "location_id" integer not null, "schedule" text, "created_at" datetime, "updated_at" datetime, foreign key("location_id") references locations("id") on delete no action on update cascade, foreign key("doctor_id") references "doctors"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "category_ages" ("id" integer primary key autoincrement not null, "title" text not null, "age" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "categories" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "health_screening_categories" ("id" integer primary key autoincrement not null, "title" text not null, "icon" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "health_screenings" ("id" integer primary key autoincrement not null, "title" text not null, "slug" text not null, "gender" text not null, "price" double not null, "description" text not null, "image" text not null, "health_screening_category_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("health_screening_category_id") references "health_screening_categories"("id") on update cascade);
CREATE TABLE IF NOT EXISTS "health_screening_has_locations" ("id" integer primary key autoincrement not null, "health_screening_id" integer not null, "location_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("health_screening_id") references "health_screenings"("id") on delete cascade, foreign key("location_id") references "locations"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "health_screening_has_ages" ("id" integer primary key autoincrement not null, "health_screening_id" integer not null, "age_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("health_screening_id") references "health_screenings"("id") on delete cascade, foreign key("age_id") references "category_ages"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "offers_categories" ("id" integer primary key autoincrement not null, "title" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "offers" ("id" integer primary key autoincrement not null, "title" text not null, "slug" text not null, "image" text, "content" text, "offers_category_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("offers_category_id") references "offers_categories"("id"));
CREATE TABLE IF NOT EXISTS "offer_has_locations" ("id" integer primary key autoincrement not null, "offer_id" integer not null, "location_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("offer_id") references "offers"("id") on delete cascade, foreign key("location_id") references "locations"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "settings" ("id" integer primary key autoincrement not null, "name" varchar not null, "value" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "sliders" ("id" integer primary key autoincrement not null, "index" integer, "title" varchar, "description" varchar, "image" varchar not null, "created_at" datetime, "updated_at" datetime, "status" tinyint(1) not null default ('0'));
CREATE TABLE IF NOT EXISTS "menu_headers" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar, "route_name" varchar, "icon" varchar, "index" varchar, "is_active" tinyint(1) not null default ('1'), "created_at" datetime, "updated_at" datetime, "page_id" integer, foreign key("page_id") references "pages"("id") on update cascade);
CREATE TABLE IF NOT EXISTS "menu_footers" ("id" integer primary key autoincrement not null, "title" varchar not null, "page_id" integer, "slug" varchar, "route_name" varchar, "icon" varchar, "index" varchar, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("page_id") references "pages"("id") on update cascade);
CREATE TABLE IF NOT EXISTS "career_submissions" ("id" integer primary key autoincrement not null, "full_name" varchar not null, "email" varchar not null, "job_title" varchar not null, "location" varchar not null, "phone" varchar not null, "province" varchar not null, "city" varchar not null, "cv" text not null, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "services_slug_unique" on "services" ("slug");
CREATE UNIQUE INDEX "subservices_slug_unique" on "subservices" ("slug");
CREATE UNIQUE INDEX "facilities_slug_unique" on "facilities" ("slug");
CREATE UNIQUE INDEX "emergencies_slug_unique" on "emergencies" ("slug");
COMMIT;
