INSERT INTO pages VALUES(9,'{"en":"Home","id":"Beranda"}','{"en":"/","id":"/"}','pages.home.index',NULL,'{"en":{"about":{"image":32,"title":"Experience peace of mind","heading":"When Your Health, Is Our Priority","button_label":"Learn More About Us","content":"<p>Altius Hospitals delivers international-standard healthcare with the genuine warmth of Indonesian hospitality. Supported by advanced medical technology and experienced professionals, we are committed to providing the highest quality care for your optimal health and peace of mind.</p>"},"testimony":{"title":"Medical Testimony","heading":"Experience trusted Healthcare"},"full_screen":{"image":33},"health_screening":{"title":"Your Health, Your Priority","heading":"Discover Our Health Screening Package","button_label":"More Health Screening Package"},"offer":{"title":"Your Health, Your Priority","heading":"Latest Offers","button_label":"Discovers More Offers"}},"id":{"about":{"image":32,"title":"Rasakan ketenangan pikiran","heading":"Ketika Kesehatan Anda, Adalah Prioritas Kami","content":"<p>Rumah Sakit Altius menyediakan layanan kesehatan berstandar internasional dengan kehangatan sejati dari keramahan Indonesia. Didukung oleh teknologi medis canggih dan tenaga profesional berpengalaman, kami berkomitmen untuk memberikan perawatan berkualitas tertinggi demi kesehatan optimal dan ketenangan pikiran Anda.</p>","button_label":"Pelajari Lebih Lanjut Tentang Kami"},"full_screen":{"image":33},"testimony":{"title":"Saksi Ahli Medis","heading":"Nikmati layanan kesehatan yang terpercaya"},"health_screening":{"title":"Kesehatan Anda, Prioritas Anda","heading":"Temukan Paket Pemeriksaan Kesehatan Kami","button_label":"Paket Pemeriksaan Kesehatan Lebih Lengkap"},"offer":{"title":"Kesehatan Anda, Prioritas Anda","heading":"Penawaran Terbaru","button_label":"Temukan Penawaran Lainnya"}}}',0,'2025-10-21 09:10:33','2025-10-23 07:08:29','App\Http\Controllers\Pages\HomeController','home',NULL);
INSERT INTO pages VALUES(10,'{"en":"About Altius Hospitals","id":"Tentang Rumah Sakit Altius"}','{"en":"about","id":"tentang"}','pages.about.index','36','{"en":{"heading":{"heading":"Altius Hospitals is a hospital built by doctors","colored_heading":"with best practices in mind"},"about_us":{"image":22,"title":"Who we are","heading":"The Story of Altius Hospitals","content":"<p>Altius Hospitals was founded from the dream of Dr. Hartoyo Sutandar, a pioneer of Indonesian cardiology in the 1980s. He was a cardiology trailblazer who developed the field in Indonesia and taught at universities like the University of Indonesia. From there, he ventured into the business world, becoming involved in the pharmaceutical and medical device industries.</p><p>With his extensive knowledge in healthcare, Dr. Sutandar dreamed of building a hospital to make a greater impact on patients&#039; lives. Altius Hospitals embodies Dr. Sutandar&#039;s core value that &quot;people should have access to high-quality healthcare.&quot;</p>"},"about_us_2":{"title":"Who we are","heading":"The Genesis of Altius Hospitals","image":23,"content":"<p>Altius Hospitals was founded from the dream of Dr. Hartoyo Sutandar, a pioneer of Indonesian cardiology in the 1980s. He was a cardiology trailblazer who developed the field in Indonesia and taught at universities like the University of Indonesia. From there, he ventured into the business world, becoming involved in the pharmaceutical and medical device industries.</p><p>With his extensive knowledge in healthcare, Dr. Sutandar dreamed of building a hospital to make a greater impact on patients&#039; lives. Altius Hospitals embodies Dr. Sutandar&#039;s core value that &quot;people should have access to high-quality healthcare.&quot;</p>"},"vision":{"vision":"Our objective is to cultivate an optimal work environment that empowers our staff to excel, feel esteemed, find satisfaction in their roles, and consistently deliver compassionate, world-class healthcare and patient experiences ","mission":"A relentless pursuit to offer Indonesian communities medical services that embody integrity, reliability, high quality, innovation, and pioneering advancement","vision_image":24,"mission_image":25,"quote":"Doctors established Altius Hospitals, building it around the principles of best medical practice"},"more_about":{"grid":[{"icon":27,"title":"Professional","content":"Trusted, skilled, and experienced medical professionals committed to quality care"},{"icon":31,"title":"State-of-the-Art Technology","content":"Modern healthcare infrastructure equipped with the latest technology"},{"icon":29,"title":"Comprehensive","content":"Extensive and integrated healthcare services"},{"icon":26,"title":"Personalized","content":"Compassionate and customized care, delivered with expertise"},{"icon":28,"title":"Compassionate","content":"Supportive care in a heartwarming environment"},{"icon":30,"title":"Commitment","content":"A strong commitment to delivering quality care and ensuring patient safety."}]}},"id":{"about_us":{"image":22,"title":"Siapa kami","heading":"Kisah Rumah Sakit Altius","content":"<p>Rumah Sakit Altius didirikan dari impian Dr. Hartoyo Sutandar, seorang pionir kardiologi Indonesia pada tahun 1980-an. Beliau adalah seorang pelopor di bidang kardiologi yang mengembangkan bidang tersebut di Indonesia dan mengajar di universitas-universitas seperti Universitas Indonesia. Dari sana, beliau terjun ke dunia bisnis, terlibat dalam industri farmasi dan alat kesehatan.</p><p>Dengan pengetahuannya yang luas di bidang kesehatan, Dr. Sutandar bermimpi untuk membangun rumah sakit yang dapat memberikan dampak yang lebih besar bagi kehidupan pasien. Altius Hospitals mewakili nilai inti Dr. Sutandar bahwa “setiap orang harus memiliki akses ke layanan kesehatan berkualitas tinggi.”</p>"},"about_us_2":{"image":23,"title":"Siapa kami","heading":"Asal-usul Rumah Sakit Altius","content":"<p>Rumah Sakit Altius didirikan dari impian Dr. Hartoyo Sutandar, seorang pionir kardiologi Indonesia pada tahun 1980-an. Beliau adalah seorang pelopor di bidang kardiologi yang mengembangkan bidang tersebut di Indonesia dan mengajar di universitas-universitas seperti Universitas Indonesia. Dari sana, beliau terjun ke dunia bisnis, terlibat dalam industri farmasi dan alat kesehatan.</p><p>Dengan pengetahuannya yang luas di bidang kesehatan, Dr. Sutandar bermimpi untuk membangun rumah sakit yang dapat memberikan dampak yang lebih besar bagi kehidupan pasien. Altius Hospitals mewakili nilai inti Dr. Sutandar bahwa “setiap orang harus memiliki akses ke layanan kesehatan berkualitas tinggi.”</p>"},"vision":{"vision_image":24,"mission_image":25,"vision":"Tujuan kami adalah menciptakan lingkungan kerja yang optimal yang memberdayakan karyawan kami untuk berprestasi, merasa dihargai, menemukan kepuasan dalam peran mereka, dan secara konsisten memberikan layanan kesehatan dan pengalaman pasien yang penuh empati dan berkualitas dunia. ","mission":"Upaya yang tak kenal lelah untuk menyediakan layanan kesehatan bagi masyarakat Indonesia yang menjunjung tinggi integritas, keandalan, kualitas tinggi, inovasi, dan kemajuan terdepan.","quote":"Dokter mendirikan Rumah Sakit Altius, dengan mengedepankan prinsip-prinsip praktik medis terbaik."},"more_about":{"grid":[{"icon":27,"title":"Profesional","content":"Tenaga medis yang terpercaya, terampil, dan berpengalaman yang berkomitmen untuk memberikan perawatan berkualitas."},{"icon":31,"title":"Teknologi Terkini","content":"Infrastruktur kesehatan modern yang dilengkapi dengan teknologi terbaru"},{"icon":29,"title":"Komprehensif","content":"Layanan kesehatan yang komprehensif dan terintegrasi"},{"icon":26,"title":"Disesuaikan secara pribadi","content":"Perawatan yang penuh kasih sayang dan disesuaikan dengan kebutuhan, diberikan dengan keahlian."},{"icon":28,"title":"Penuh kasih sayang","content":"Perawatan pendukung dalam lingkungan yang hangat dan penuh kasih sayang"},{"icon":30,"title":"Komitmen","content":"Komitmen yang kuat dalam memberikan perawatan berkualitas dan memastikan keselamatan pasien."}]},"heading":{"heading":"Rumah Sakit Altius adalah rumah sakit yang didirikan oleh para dokter","colored_heading":"dengan mempertimbangkan praktik terbaik"}}}',0,'2025-10-21 09:20:33','2025-10-23 07:08:53','App\Http\Controllers\Pages\AboutController','about',NULL);
INSERT INTO pages VALUES(11,'{"en":"Our Location","id":"Lokasi Kami"}','{"en":"our-location","id":"lokasi-kami"}','pages.location.index',NULL,'{"en":{"section":{"title":"Our Location","heading":"Find an Altius Hospital near you"}},"id":{"section":{"title":"Lokasi Kami","heading":"Temukan Rumah Sakit Altius terdekat dari Anda"}}}',0,'2025-10-21 13:53:47','2025-10-23 07:09:00','App\Http\Controllers\Pages\LocationController','location','locationDetail');
INSERT INTO pages VALUES(12,'{"en":"Career","id":"Karier"}','{"en":"career","id":"karir"}','pages.career.index','35','{"en":{"section":{"heading":"Career","subheading":"Join our team and make a difference"},"body":{"title":"Build Your Career at Altius Hospitals","description":"Altius Hospitals continues to grow in its mission to provide the best healthcare services with a strong focus on patient comfort. We take pride in our team of skilled and dedicated professionals. Join us and be part of our journey!"},"warning":{"title":"Beware of Recruitment Scams!","description":"It has come to our attention that fake job offers are being made, claiming to be from Altius Hospitals. Please be aware that Altius Hospitals does not require any payment from applicants seeking employment with us."}},"id":{"section":{"heading":"Karier","subheading":"Bergabunglah dengan tim kami dan buatlah perbedaan"},"body":{"title":"Bangun Karier Anda di Rumah Sakit Altius","description":"Altius Hospitals terus berkembang dalam misinya untuk menyediakan layanan kesehatan terbaik dengan fokus yang kuat pada kenyamanan pasien. Kami bangga dengan tim profesional yang terampil dan berkomitmen. Bergabunglah dengan kami dan jadilah bagian dari perjalanan kami!"},"warning":{"title":"Waspadalah terhadap Penipuan Rekrutmen!","description":"Kami telah mengetahui bahwa ada penawaran pekerjaan palsu yang dibuat, mengklaim berasal dari Altius Hospitals. Harap diperhatikan bahwa Altius Hospitals tidak meminta pembayaran apa pun dari calon karyawan yang melamar pekerjaan di sini."}}}',0,'2025-10-21 13:56:30','2025-10-23 07:09:09','App\Http\Controllers\Pages\CareerController','career','careerDetail');
INSERT INTO pages VALUES(13,'{"en":"Health Screening","id":"Pemeriksaan Kesehatan"}','{"en":"health-screening","id":"pemeriksaan-kesehatan"}','pages.health-screening.index',NULL,'{"en":{"section":{"title":"Health Screening","heading":"Your Health in Your Hands"}},"id":{"section":{"title":"Pemeriksaan Kesehatan","heading":"Kesehatan Anda di Tangan Anda"}}}',0,'2025-10-21 13:58:17','2025-10-23 07:09:42','App\Http\Controllers\Pages\ScreeningController','screening',NULL);
