INSERT INTO pages VALUES(15,'{"en":"News","id":"Berita"}','{"en":"news","id":"berita"}','pages.news.index','34','{"en":{"section":{"heading":"News","subheading":"Stay Connected, Stay Healthy"},"body":{"heading":"Latest Blog & News","subheading":"Find out what''s happening at Altius Hospitals — from new service launches to community events and expert advice"}},"id":{"section":{"heading":"Berita","subheading":"Tetap Terhubung, Tetap Sehat"},"body":{"heading":"Blog dan Berita Terbaru","subheading":"Temukan informasi terbaru tentang Altius Hospitals — mulai dari peluncuran layanan baru, acara komunitas, hingga saran dari para ahli."}}}',0,'2025-10-21 14:00:10','2025-10-23 07:10:04','App\Http\Controllers\Pages\NewsController','news','newsDetail');
