INSERT INTO pages VALUES(17,'{"en":"Contact Us","id":"Hubungi Kami"}','{"en":"contact-us","id":"hubungi-kami"}','pages.contact.index',NULL,'{"en":{"section":{"heading":"Contact Us","subheading":"Addresses and Phone Numbers"},"staff":{"title":"Staff phone and email directories","description":"Altius Hospitals doesn''t have a public directory of staff phone numbers or email addresses. To contact someone, call the general telephone number at a Altius Hospitals location and the operator will connect you."}},"id":{"section":{"heading":"Hubungi Kami","subheading":"Alamat dan Nomor Telepon"},"staff":{"title":"Daftar telepon dan email karyawan","description":"Rumah Sakit Altius tidak memiliki direktori publik yang berisi nomor telepon atau alamat email staf. Untuk menghubungi seseorang, hubungi nomor telepon umum di lokasi Rumah Sakit Altius, dan operator akan menghubungkan Anda."}}}',0,'2025-10-23 08:33:05','2025-10-23 08:35:42','App\Http\Controllers\Pages\ContactController','contact',NULL);
INSERT INTO pages VALUES(18,'{"en":"Privacy Policy","id":"Kebijakan Privasi"}','{"en":"privacy-policy","id":"kebijakan-privasi"}','pages.privacy.index',NULL,'{"en":{"faq":{"8f82a54e-1434-4fb5-badb-7109b7cdee11":{"title_en":null,"content_en":null,"title_id":null,"content_id":null,"title":"What information does Altius Hospitals collect?","content":{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Altius Hospitals may obtain various types of information when Users use the “Contact > Contact Us” service, or send us an email, or post information or other content on the website, or when users register for an account. We also collect information about Personal Data that Users are required to fill in when registering for the Service."}]},{"type":"paragraph","attrs":{"textAlign":"start"}},{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Altius Hospitals will automatically collect information regarding the number of visits and visitor activity for the purpose of improving user comfort."}]},{"type":"paragraph","attrs":{"textAlign":"start"}},{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Altius Hospitals'' servers also automatically record and collect Log File information when Users use the website, including but not limited to: Internet Protocol (IP) address, location data, browser type, browser language, referring pages and URLs, number of clicks, domain names, telephone numbers, and up to 1 or more cookies that can uniquely identify a user''s browser."}]},{"type":"paragraph","attrs":{"textAlign":"start"}},{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"This information may reveal the habits, preferences, favorite searches of users, or any other information related to users."}]},{"type":"paragraph","attrs":{"textAlign":"start"}},{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Users guarantee that the information provided is accurate and correct. If there is any indication that the information provided is incorrect, Altius Hospitals is not responsible for any consequences that may arise in connection with the provision and use of such information."}]}]}},"167cdfbe-4244-4f9d-b3f4-f20a55186b5b":{"title":"How Does Altius Hospitals Use Information?","content":{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"When Users submit Personal Identity Information to Altius Hospitals, we use that information in accordance with the User''s request related to Altius Hospitals Website Services."}]},{"type":"paragraph","attrs":{"textAlign":"start"}},{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Altius Hospitals will use the User''s information to contact the User and remind them of the services created through the website. In addition, the User''s information will be used and disclosed if necessary for medical review, legal services, or audits."}]},{"type":"paragraph","attrs":{"textAlign":"start"}},{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Altius Hospitals guarantees that the data and information provided by the User is confidential and will not be disclosed."}]}]}},"acf1ec1d-2ea0-4bfe-a892-f95ce7320331":{"title":"When does Altius Hospitals disclose information?","content":{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Altius Hospitals may provide Personal Data or non-personal identification information to third-party service providers as reasonably necessary. Users are deemed to have consented to and permitted third parties to access and use such data."}]},{"type":"paragraph","attrs":{"textAlign":"start"}},{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Such third parties include Companies or Insurance Providers and Doctors."}]}]}},"f308e085-3508-4b8a-bcef-d0ca84c2aa5c":{"title":"Altius Hospitals'' Commitment to Data Security","content":{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Altius Hospitals respects the privacy and security of User data. In order to maintain our commitment and integrity to the security of Users'' personal information, we will use all access to information commercially in a reasonable manner and it cannot be used by irresponsible parties."}]},{"type":"paragraph","attrs":{"textAlign":"start"}},{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"The storage of Users'' personal data in database servers is done to provide reasonable protection."}]},{"type":"paragraph","attrs":{"textAlign":"start"}},{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"However, Altius Hospitals cannot fully guarantee this security, so any information that Users send may still be intercepted by third parties. Therefore, in using the Website Services, Users do so at their own risk."}]},{"type":"paragraph","attrs":{"textAlign":"start"}},{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"We advise Users not to use unprotected networks or unsecured WiFi."}]}]}},"7bda8eb0-4d02-4adf-ae19-1c690f18b516":{"title":"Changes and updates to the Privacy Policy","content":{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Altius Hospitals reserves the right to change, delete, or add new provisions to this Privacy Policy. Users are expected to periodically review the Privacy Policy page to be aware of such changes."}]},{"type":"paragraph","attrs":{"textAlign":"start"}},{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Users expressly acknowledge that they have read the terms and conditions of service. This Privacy Policy is governed by the laws of the Republic of Indonesia, and Users are required to comply with all applicable regulations in Indonesia."}]}]}},"dbd63f39-8c9c-40a0-aa5a-1403ff2ebc7c":{"title":"Contact Information, Questions, and Complaints","content":{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"If you have any questions about this Privacy Policy, your rights, or anything else related to the use of the Website, please send an email to "},{"type":"text","text":"care@altiushospitals.id","marks":[{"type":"link","attrs":{"href":"mailto:care@altiushospitals.id"}}]}]}]}}},"content_en":null,"content_id":null,"content":{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Altius Hospitals respects the privacy of website users and is committed to protecting it seriously. This Privacy Policy is designed to help Users understand how Altius Hospitals and/or our subsidiaries collect, use, share, and protect information while respecting Users'' rights in using the "},{"type":"text","text":"altiushospitals.id","marks":[{"type":"link","attrs":{"href":"http://altiushospitals.id"}}]},{"type":"text","text":" website."}]},{"type":"paragraph","attrs":{"textAlign":"start"}},{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"The use of Altius Hospitals'' Services and any personal information provided by users must always comply with the terms and conditions of this Privacy Policy."}]}]}},"id":{"faq":[{"title":"Informasi apa yang Altius Hospitals kumpulkan?","content":"<p>Altius Hospitals dapat memperoleh berbagai jenis informasi saat Pengguna menggunakan layanan “Kontak &gt; Hubungi Kami”, atau mengirimkan surat elektronik / e-mail kepada kami atau meletakkan informasi atau konten lain di website atau saat pengguna mendaftarkan akun. Kami juga mengumpulkan informasi mengenai Data Pribadi yang wajib diisi oleh Pengguna saat melakukan Registrasi Layanan,</p><p>Altius Hospitals akan mengumpulkan informasi secara otomatis mengenai jumlah kunjungan dan aktivitas pengunjung dengan tujuan untuk meningkatkan kenyamanan Pengguna.</p><p>Server Altius Hospitals secara otomatis juga mencatat dan mengumpulkan informasi Log File ketika Pengguna menggunakan website, termasuk tetapi tidak terbatas pada: alamat Internet Protocol (IP), data lokasi, jenis browser, bahasa browser, halaman dan URL perujuk, jumlah klik, nama domain, nomor telepon, hingga 1 atau lebih cookies yang secara unik dapat mengidentifikasi browser pengguna.</p><p>Informasi tersebut dapat memperlihatkan kebiasaan, keinginan, pencarian favorit dari pengguna maupun setiap informasi lain yang terkait dengan pengguna.</p><p>Pengguna menjamin bahwa informasi yang diberikan adalah akurat dan benar. Apabila ditemukan adanya indikasi informasi yang diberikan tidak benar, maka Altius Hospitals tidak bertanggung jawab atas segala akibat yang dapat terjadi sehubungan dengan pemberian dan penggunaan informasi tersebut.</p>"},{"title":"Bagaimana Cara Altius Hospitals Menggunakan Informasi?","content":"<p>Apabila Pengguna mengirim Informasi Identitas Pribadi kepada Altius Hospitals, maka kami menggunakan informasi tersebut sesuai permintaan Pengguna yang berkaitan dengan Layanan Website Altius Hospitals.</p><p>Altius Hospitals akan menggunakan informasi Pengguna untuk menghubungi Pengguna dan mengingatkan mengenai layanan yang dibuat melalui website. Selain itu, informasi Pengguna akan digunakan dan diungkapkan jika diperlukan sebagai tinjauan medis, jasa hukum, maupun audit.</p><p>Altius Hospitals menjamin bahwa data dan informasi yang diberikan Pengguna bersifat rahasia dan tidak akan disebarluaskan.</p>"},{"title":"Kapan Altius Hospitals mengungkapkan informasi?","content":"<p>Altius Hospitals dapat memberikan Informasi Data Pribadi atau informasi identifikasi non pribadi kepada penyedia layanan pihak ketiga selama diperlukan secara wajar. Pengguna dianggap telah menyetujui dan mengizinkan pihak ketiga mengetahui dan menggunakan data tersebut.</p><p>Pihak ketiga tersebut termasuk Perusahaan atau Asuransi Penjamin dan Dokter</p>"},{"title":"Komitmen Altius Hospitals Terhadap Keamanan Data","content":"<p>Altius Hospitals menghormati privasi dan keamanan data Pengguna. Demi menjaga komitmen dan integritas terhadap keamanan informasi pribadi Pengguna, kami akan menggunakan seluruh akses informasi secara komersial dengan cara wajar dan tidak dapat digunakan oleh pihak-pihak yang tidak bertanggung jawab.</p><p>Penyimpanan data pribadi Pengguna dalam server database dilakukan untuk memberikan perlindungan yang wajar.</p><p>Namun demikian, Altius Hospitals tidak bisa menjamin sepenuhnya terhadap keamanan ini sehingga setiap informasi yang Pengguna kirimkan masih mungkin dapat dibajak oleh pihak ketiga. Untuk itu, dalam menggunakan Layanan Website, Pengguna melakukannya atas risiko Pengguna sendiri.</p><p>Kami menyarankan Pengguna untuk tidak menggunakan jaringan yang tidak terlindungi atau WiFi yang tidak aman.</p>"},{"title":"Perubahan dan pemutakhiran Kebijakan Privasi","content":"<p>Perubahan, penghapusan, maupun penambahan ketentuan baru pada Kebijakan Privasi ini merupakan Hak Altius Hospitals sepenuhnya. Pengguna diharapkan melakukan pemeriksaan halaman Kebijakan Privasi secara berkala untuk mengetahui perubahan tersebut.</p><p>Pengguna secara tegas mengaku telah membaca syarat dan ketentuan layanan. Kebijakan Privasi ini diatur berdasarkan hukum Republik Indonesia sehingga Pengguna diwajibkan tunduk kepada semua peraturan yang berlaku di Indonesia.</p>"},{"title":"Kontak Informasi, Pertanyaan, dan Keluhan","content":"<p>Apabila Pengguna memiliki pertanyaan tentang Kebijakan Privasi ini, Hak Pengguna, maupun hal lain terkait penggunaan Website, silahkan mengirim email ke <a href=\"care@altiushospitals.id\" data-as-button=\"false\">care@altiushospitals.id</a></p>"}],"content_en":null,"content_id":null,"content":"<p>Altius Hospitals menghormati privasi pengguna website dan berkomitmen untuk menjaganya dengan serius. Kebijakan Privasi ini dibuat untuk membantu Pengguna agar mengetahui bagaimana cara Altius Hospitals dan/atau anak perusahaan kami dalam mengumpulkan, menggunakan, membagikan, dan melindungi informasi dengan tetap menghormati Hak Pengguna dalam menggunakan situs <a href=\"http://altiushospitals.id\">altiushospitals.id</a></p><p>Penggunaan atas Layanan Altius Hospitals beserta setiap informasi pribadi yang diberikan oleh Pengguna, harus senantiasa tunduk pada syarat dan ketentuan Kebijakan Privasi.</p>"}}',0,'2025-10-24 07:01:03','2025-10-24 07:48:07','App\Http\Controllers\Pages\PrivacyController','privacy',NULL);
