INSERT INTO locations VALUES(1,'{"en":"Altius Hospitals Harapan Indah"}','{"en":"altius-hospitals-harapan-indah"}','{"en":"Altius Hospitals Harapan Indah"}','{"en":"When Your Health Is Our Priority"}','{"en":"<p>Altius Hospitals, established in 2023, is a multi-specialty general hospital located in Kota Harapan Indah, Bekasi. We are a hospital founded by doctors and healthcare professionals, with the goal of providing patient-centered care.&nbsp;</p><p>&nbsp;We aim to be a leading healthcare provider, focusing on patient experience and well-being. We have three main clinical departments: Obstetrics and Gynecology + Pediatrics, Orthopedics, and Heart, Lung and Breathing</p>"}','{"en":2}','{"en":"Jl. Harapan Indah Boulevard Sektor V, Pusaka Rakyat, Kec. Tarumajaya, Kab. Bekasi, Jawa Barat 17214"}','{"en":"021-3000 8877"}','{"en":"0857 8877 8877"}','{"en":"https://maps.app.goo.gl/7MXPsZJkdr1bqq4AA"}','{"en":"<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d5010.180261315358!2d106.98206359999999!3d-6.154437099999999!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e698b3ab886b6fb%3A0x781659f27c35be4e!2sAltius%20Hospitals%20Harapan%20Indah!5e1!3m2!1sen!2sid!4v1759898052402!5m2!1sen!2sid\" width=\"400\" height=\"300\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>"}',1,'2025-10-08 04:34:27','2025-10-08 04:34:27',1,'{"en":2}','["7","28","3"]');
INSERT INTO locations VALUES(2,'{"en":"Altius Hospitals Puri Indah"}','{"en":"altius-hospitals-puri-indah"}','{"en":"Altius Hospitals Puri Indah"}','{"en":"When Your Health Is Our Priority"}','{"en":"<p>Altius Hospitals, established in 2023, is a multi-specialty general hospital located in Kota Harapan Indah, Bekasi. We are a hospital founded by doctors and healthcare professionals, with the goal of providing patient-centered care. </p><p> We aim to be a leading healthcare provider, focusing on patient experience and well-being. We have three main clinical departments: Obstetrics and Gynecology + Pediatrics, Orthopedics, and Heart, Lung and Breathing</p>"}','{"en":2}','{"en":"Jl. Harapan Indah Boulevard Sektor V, Pusaka Rakyat, Kec. Tarumajaya, Kab. Bekasi, Jawa Barat 17214"}','{"en":"021-3000 8877"}','{"en":"0857 8877 8877"}','{"en":"https://maps.app.goo.gl/7MXPsZJkdr1bqq4AA"}','{"en":"<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d5010.180261315358!2d106.98206359999999!3d-6.154437099999999!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e698b3ab886b6fb%3A0x781659f27c35be4e!2sAltius%20Hospitals%20Harapan%20Indah!5e1!3m2!1sen!2sid!4v1759898052402!5m2!1sen!2sid\" width=\"400\" height=\"300\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>"}',1,'2025-10-14 07:38:51','2025-10-14 07:38:51',2,'{"en":2}','["7","28","3"]');
