INSERT INTO careers VALUES(1,NULL,'{"en":"medical-record-staff","id":"staf-rekam-medis"}','{"en":"Medical Record Staff","id":"Staf Rekam Medis"}',1,3,'{"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Minimum Bachelor’s Degree from Medical Records major"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Have 3 years of experience from related fields"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Have a good leadership and good communication, service excellence"}]}]}]}]},"id":"<ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p>Sarjana (S1) dalam bidang Rekam Medis</p></li><li><p>Memiliki pengalaman minimal 3 tahun di bidang terkait</p></li><li><p>Memiliki kemampuan kepemimpinan yang baik, komunikasi yang baik, dan pelayanan yang unggul</p></li></ul>"}','{"en":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Responsible for the implementation of all registration activities and medical records in the hospital"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Take care of the process of completing administration / medical record correspondence"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Develop a draft medical record SOP and service flow"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Organize and organize medical record file storage"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Input medical record data from status into hospital system"}]}]}]}]},"id":"<ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p>Bertanggung jawab atas pelaksanaan semua kegiatan pendaftaran dan rekam medis di rumah sakit</p></li><li><p>Mengurus proses penyelesaian administrasi/korespondensi rekam medis</p></li><li><p>Mengembangkan draf SOP rekam medis dan alur layanan</p></li><li><p>Mengorganisir dan menyimpan berkas rekam medis</p></li><li><p>Menginput data rekam medis dari status ke sistem rumah sakit</p></li></ul>"}','2025-10-13 09:22:29','2025-10-14 02:18:28');
INSERT INTO careers VALUES(3,NULL,'{"en":"sales-executive","id":"eksekutif-penjualan"}','{"en":"Sales Executive","id":"Eksekutif Penjualan"}',1,4,'{"en":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Bachelor’s Degree with at least 1 year of working experience in the related field, fresh graduates are welcome to apply."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Proved experience in Sales marketing field"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Creative individual with high agility and adaptability"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Ability to build strong relationships with clients and customers"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Excellent interpersonal, communication, presentation, and negotiation skills"}]}]}]}]},"id":"<ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p>Gelar Sarjana dengan pengalaman kerja minimal 1 tahun di bidang terkait, lulusan baru dipersilakan untuk melamar.</p></li><li><p>Pengalaman terbukti di bidang pemasaran dan penjualan.</p></li><li><p>Individu kreatif dengan ketangkasan dan kemampuan beradaptasi yang tinggi.</p></li><li><p>Kemampuan untuk membangun hubungan yang kuat dengan klien dan pelanggan.</p></li><li><p>Keterampilan interpersonal, komunikasi, presentasi, dan negosiasi yang sangat baik.</p></li></ul>"}','{"en":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Coordinate and implement sales & marketing programs to enlarge business segment."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Strengthen brand awareness in society, align with marketing programs"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Work closely with related departments to develop new packages / services that is in line with the trend"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Build long-term partnerships with various stakeholders to develop the hospital business"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Build cross-functional relationships with organizational stakeholders to understand products, services, and industry trend to develop focused communications program"}]}]}]}]},"id":"<ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p>Mengkoordinasikan dan melaksanakan program penjualan &amp; pemasaran untuk memperluas segmen bisnis.</p></li><li><p>Memperkuat kesadaran merek di masyarakat, selaras dengan program pemasaran.</p></li><li><p>Bekerja sama dengan departemen terkait untuk mengembangkan paket / layanan baru yang sesuai dengan tren.</p></li><li><p>Membangun kemitraan jangka panjang dengan berbagai pemangku kepentingan untuk mengembangkan bisnis rumah sakit.</p></li><li><p>Membangun hubungan lintas fungsional dengan pemangku kepentingan organisasi untuk memahami produk, layanan, dan tren industri guna mengembangkan program komunikasi yang terfokus.</p></li></ul>"}','2025-10-14 02:14:03','2025-10-14 02:24:59');
INSERT INTO careers VALUES(4,NULL,'{"en":"radiographer","id":"radiografer"}','{"en":"Radiographer","id":"Radiografer"}',1,6,'{"en":"<ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p>Valid and active medical license</p></li><li><p>Proficient in general radiology techniques, including X-ray, MRI, and ultrasound.</p></li><li><p>Patient management skills.</p></li><li><p>Bachelor’s degree in Radiography</p></li></ul>","id":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Lisensi medis yang sah dan berlaku"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Mahir dalam teknik radiologi umum, termasuk sinar-X, MRI, dan ultrasonografi."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Kemampuan dalam pengelolaan pasien."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Gelar Sarjana dalam Radiografi"}]}]}]}]}}','{"en":"<ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p>Evaluating patients’ medical histories</p></li><li><p>Suggesting alternative medical imaging techniques, when necessary.</p></li><li><p>Informing patients about the medical imaging process.</p></li><li><p>Using devices such as computer tomography (CT) scanners and magnetic resonance imaging (MRI) machines.</p></li><li><p>Performing or directing radiology staff to carry out image-guided, diagnostic procedures.</p></li><li><p>Interpreting the results from diagnostic imaging procedures to determine diagnoses.</p></li><li><p>Following medical protocols for resuscitation, bleeding, infection, or other emergency situations, when necessary</p></li></ul>","id":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;","class":null},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Evaluating patients’ medical histories"}]}],"attrs":{"class":null,"style":null}},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Suggesting alternative medical imaging techniques, when necessary."}]}],"attrs":{"class":null,"style":null}},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Informing patients about the medical imaging process."}]}],"attrs":{"class":null,"style":null}},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Using devices such as computer tomography (CT) scanners and magnetic resonance imaging (MRI) machines."}]}],"attrs":{"class":null,"style":null}},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Performing or directing radiology staff to carry out image-guided, diagnostic procedures."}]}],"attrs":{"class":null,"style":null}},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Interpreting the results from diagnostic imaging procedures to determine diagnoses."}]}],"attrs":{"class":null,"style":null}},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Following medical protocols for resuscitation, bleeding, infection, or other emergency situations, when necessary"}]}],"attrs":{"class":null,"style":null}}]}]}}','2025-10-14 02:17:00','2025-10-14 02:35:45');
INSERT INTO careers VALUES(5,NULL,'{"en":"nurse-outpatientinpatient-care","id":"perawat-rawat-jalanrawat-inap"}','{"en":"Nurse – Outpatient/Inpatient Care","id":"Perawat – Rawat Jalan/Rawat Inap"}',1,1,'{"en":"<ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p>Graduated in Nursing major</p></li><li><p><strong>Preferably</strong> have certification in ACLS/ BTCLS/ ICU</p></li><li><p>Proven at least 2 years of experience in the same position</p></li><li><p>Excellent in details, hospitality skills, including the ability to listen and serve people</p></li></ul>","id":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;","class":null},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Lulusan Sarjana Keperawatan"}]}],"attrs":{"class":null,"style":null}},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Diutamakan memiliki sertifikasi ACLS/ BTCLS/ ICU","marks":[{"type":"bold"}]}]}],"attrs":{"class":null,"style":null}},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Memiliki pengalaman minimal 2 tahun di posisi yang sama"}]}],"attrs":{"class":null,"style":null}},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Memiliki kemampuan detail yang baik, keterampilan pelayanan, termasuk kemampuan mendengarkan dan melayani orang"}]}],"attrs":{"class":null,"style":null}}]}]}}','{"en":"<ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p>Assessing patients and gaining their trust</p></li><li><p>Planning and delivering patient’s care</p></li><li><p>Taking samples, pulses, temperatures and blood pressures</p></li><li><p>Monitoring and administering medication progress</p></li><li><p>Writing records and input to the system</p></li><li><p>Providing emotional support to patients and relatives</p></li><li><p>Reports to Nurse Coordinator</p></li></ul>","id":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Menilai pasien dan membangun kepercayaan mereka"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Merencanakan dan memberikan perawatan pasien"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Mengambil sampel, memeriksa denyut nadi, suhu tubuh, dan tekanan darah"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Memantau dan memberikan obat-obatan"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Menulis catatan dan memasukkan data ke sistem"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Memberikan dukungan emosional kepada pasien dan keluarga mereka"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Melaporkan kepada Koordinator Perawat"}]}]}]}]}}','2025-10-14 02:21:20','2025-10-14 06:23:34');
INSERT INTO careers VALUES(6,NULL,'{"en":"pharmacy-manager","id":"manajer-apotek"}','{"en":"Pharmacy Manager","id":"Manajer Apotek"}',1,5,'{"en":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Graduated from Pharmacy degree and Apothecary with usable STRA (Surat Tanda Registrasi Apoteker)"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Has experience on handling PBBF is preferable"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Willing to Administer Pharmacy Practice License (SIPA/Surat Ijin Praktek Apoteker)"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Have a minimum of 2 years experience as Head of Pharmacy Department / Head of Pharmacy Installation in a Hospital."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Have good knowledge and understanding of the strategy and flow of hospital pharmaceutical services (Inpatient, Outpatient, Clinical Pharmacy, Pharmaceutical Logistics, etc.)."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Able to prepare and carry out continuous improvement programs for pharmaceutical services."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Have good leadership and communication skills."}]}]}]}]},"id":"<ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p>Lulusan program Sarjana Farmasi dan Apoteker dengan STRA (Surat Tanda Registrasi Apoteker) yang masih berlaku.</p></li><li><p>Memiliki pengalaman dalam menangani PBBF diutamakan.</p></li><li><p>Bersedia mengurus Surat Izin Praktek Apoteker (SIPA).</p></li><li><p>Memiliki pengalaman minimal 2 tahun sebagai Kepala Departemen Farmasi / Kepala Instalasi Farmasi di Rumah Sakit.</p></li><li><p>Memiliki pengetahuan dan pemahaman yang baik mengenai strategi dan alur layanan farmasi rumah sakit (Rawat Inap, Rawat Jalan, Farmasi Klinik, Logistik Farmasi, dll).</p></li><li><p>Mampu menyiapkan dan melaksanakan program peningkatan berkelanjutan untuk layanan farmasi.</p></li><li><p>Memiliki kemampian kepemimpinan dan komunikasi yang baik.</p></li></ul>"}','{"en":""}','2025-10-14 02:27:13','2025-10-14 02:32:16');
INSERT INTO careers VALUES(7,NULL,'{"en":"admission-cashier-hospital","id":"pendaftaran-kasir-rumah-sakit"}','{"en":"Admission & Cashier – Hospital","id":"Pendaftaran & Kasir – Rumah Sakit"}',1,2,'{"en":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Minimum Diploma Degree majoring in Keperawatan, Farmasi, Kesehatan Masyarakat"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Proven 2 years of experience in hospital as admission/front liners services"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Patient-focused, experience in managing complaints & feedback"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Strong communication and interpersonal skills"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Lives in/near Bekasi"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Clean and neat appearance"}]}]}]}]},"id":"<ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p>Ijazah Diploma minimal dengan jurusan Keperawatan, Farmasi, atau Kesehatan Masyarakat</p></li><li><p>Pengalaman minimal 2 tahun di rumah sakit sebagai petugas penerimaan/layanan garis depan</p></li><li><p>Berorientasi pada pasien, berpengalaman dalam menangani keluhan dan masukan</p></li><li><p>Kemampuan komunikasi dan interpersonal yang kuat</p></li><li><p>Tinggal di/dekat Bekasi</p></li><li><p>Penampilan rapi dan bersih</p></li></ul>"}','{"en":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Manage patient pre-admission process"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Answer patient questions regarding admission procedures"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Screen patients’ medical insurance and payment information validity and verify third-party approvals when necessary"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Guide patients through the admission process and gather relevant personal information through pre-admission interviews"}]}]}]}]},"id":"<ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p>Mengelola proses pra-rawat inap pasien</p></li><li><p>Menjawab pertanyaan pasien mengenai prosedur rawat inap</p></li><li><p>Memverifikasi keabsahan asuransi kesehatan dan informasi pembayaran pasien, serta mengonfirmasi persetujuan pihak ketiga jika diperlukan</p></li><li><p>Membimbing pasien melalui proses rawat inap dan mengumpulkan informasi pribadi yang relevan melalui wawancara pra-rawat inap</p></li></ul>"}','2025-10-14 02:29:36','2025-10-14 02:34:01');
INSERT INTO careers VALUES(8,NULL,'{"en":"medical-record-coordinator","id":"koordinator-rekam-medis"}','{"en":"Medical Record Coordinator","id":"Koordinator Rekam Medis"}',1,3,'{"en":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Minimum Bachelor’s Degree from Medical Records major"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Have 3 years of experience from related fields"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Have a good leadership and good communication, service excellence"}]}]}]}]},"id":"<ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p>Minimal Gelar Sarjana dari jurusan Rekam Medis.</p></li><li><p>Memiliki pengalaman 3 tahun di bidang terkait.</p></li><li><p>Memiliki kemampuan kepemimpinan dan komunikasi yang baik, serta pelayanan prima.</p></li></ul>"}','{"en":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Responsible for the implementation of all registration activities and medical records in the hospital"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Take care of the process of completing administration / medical record correspondence"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Develop a draft medical record SOP and service flow"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Organize and organize medical record file storage"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Input medical record data from status into hospital system"}]}]}]}]},"id":"<ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p>Bertanggung jawab atas pelaksanaan semua kegiatan registrasi dan rekam medis di rumah sakit.</p></li><li><p>Mengurus proses penyelesaian administrasi / surat menyurat rekam medis.</p></li><li><p>Menyusun draft SOP rekam medis dan alur layanan.</p></li><li><p>Menata dan mengatur penyimpanan berkas rekam medis.</p></li><li><p>Memasukkan data rekam medis dari status ke dalam sistem rumah sakit.</p></li></ul>"}','2025-10-14 02:35:09','2025-10-14 02:45:16');
INSERT INTO careers VALUES(9,NULL,'{"en":"nurse-igd","id":"perawat-igd"}','{"en":"Nurse – IGD","id":"Perawat – IGD"}',1,1,'{"en":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Min. D3 in Nursing"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Must have ACLS / BTCLS training Emergency"}]}]}]}]},"id":"<ul><li><p>Min. D3 dalam Keperawatan</p></li><li><p>Harus memiliki pelatihan ACLS / BTCLS untuk keadaan darurat</p></li></ul>"}','{"en":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Being ready to respond and equipped to deal with a medical emergency."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Quickly assessing patient needs."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Treating critical injuries, allergic reactions, and trauma."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Performing minor medical operations."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Cleaning wounds."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Drawing blood."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Maintaining emergency room care standards."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Assisting with insurance paperwork."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Ensuring the efficiency of the patient check-in process."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Displaying strong decision-making skills in emergency scenarios."}]}]}]}]},"id":"<ul><li><p>Siap merespons dan dilengkapi untuk menangani keadaan darurat medis.</p></li><li><p>Menilai kebutuhan pasien dengan cepat.</p></li><li><p>Menangani luka kritis, reaksi alergi, dan trauma.</p></li><li><p>Melakukan prosedur medis minor.</p></li><li><p>Membersihkan luka.</p></li><li><p>Mengambil darah.</p></li><li><p>Menjaga standar perawatan di ruang gawat darurat.</p></li><li><p>Membantu dalam pengurusan dokumen asuransi.</p></li><li><p>Memastikan efisiensi proses pendaftaran pasien.</p></li><li><p>Menunjukkan kemampuan pengambilan keputusan yang kuat dalam situasi darurat.</p></li></ul>"}','2025-10-14 02:35:58','2025-10-14 02:48:53');
INSERT INTO careers VALUES(10,NULL,'{"en":"nurse-icu","id":"perawat-icu"}','{"en":"Nurse – ICU","id":"Perawat – ICU"}',1,1,'{"en":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Minimum D3"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Have at least 3 years ICU experience"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Have ICU certificate"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Have ACLS certificate"}]}]}]}]},"id":"<ul><li><p>Minimal D3</p></li><li><p>Memiliki pengalaman minimal 3 tahun di ICU</p></li><li><p>Memiliki sertifikat ICU</p></li><li><p>Memiliki sertifikat ACLS</p></li></ul>"}','{"en":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Evaluate and monitor the patient’s progress."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Identify sudden or subtle changes in a patient’s medical condition."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Deliver regular updates to doctors, patients, and their family members."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Begin treatment and monitor doses."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Care for patient needs throughout their recovery in the ICU unit."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Complete all necessary paperwork before transferring a patient."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Maintain patient records."}]}]}]}]},"id":"<ul><li><p>Evaluasi dan pantau perkembangan pasien.</p></li><li><p>Identifikasi perubahan mendadak atau halus dalam kondisi medis pasien.</p></li><li><p>Berikan pembaruan rutin kepada dokter, pasien, dan anggota keluarga mereka.</p></li><li><p>Mulai pengobatan dan pantau dosis.</p></li><li><p>Layani kebutuhan pasien selama proses pemulihan di unit ICU.</p></li><li><p>Lengkapi semua dokumen yang diperlukan sebelum memindahkan pasien.</p></li><li><p>Jaga catatan medis pasien.</p></li></ul>"}','2025-10-14 02:46:13','2025-10-14 06:20:07');
INSERT INTO careers VALUES(12,NULL,'{"en":"nurse-cssd","id":"perawat-cssd"}','{"en":"Nurse – CSSD","id":"Perawat – CSSD"}',1,1,'{"en":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Min. D3 in Nursing"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Have CSSD experience in hospital"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Have certificate about CSSD"}]}]}]}]},"id":"<ul><li><p>Minimal D3 dalam Keperawatan</p></li><li><p>Memiliki pengalaman di CSSD di rumah sakit</p></li><li><p>Memiliki sertifikat tentang CSSD</p></li></ul><p></p>"}','{"en":{"type":"doc","content":[{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Handle all equipment’s with care and cleaning through the standard instrument processing."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Clean, disinfect and pack the medical instruments for sterilization based on the instrument processing of the department."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Keeping the facility’s stock of sterile devices up to date by regular inventory of stocks."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Identification of surgical instrumentation by proper name and appropriate sterilization method."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Report immediately broken or malfunctioning equipment to charge nurse."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Maintains a safe and clean working environment in compliance with healthcare procedures and regulations."}]}]}]}]},"id":"<ul><li><p>Tangani semua peralatan dengan hati-hati dan bersihkan melalui proses pengolahan alat standar.</p></li><li><p>Bersihkan, desinfeksi, dan kemas alat medis untuk sterilisasi sesuai dengan prosedur pengolahan alat di departemen.</p></li><li><p>Menjaga persediaan alat steril di fasilitas tetap terkini melalui inventarisasi rutin.</p></li><li><p>Identifikasi alat bedah dengan nama yang tepat dan metode sterilisasi yang sesuai.</p></li><li><p>Laporkan segera peralatan yang rusak atau tidak berfungsi kepada perawat jaga.</p></li><li><p>Menjaga lingkungan kerja yang aman dan bersih sesuai dengan prosedur dan peraturan kesehatan.</p></li></ul>"}','2025-10-14 02:56:56','2025-10-14 04:58:49');
INSERT INTO news_categories VALUES(1,'{"en":"News","id":"Berita"}','2025-10-14 02:17:08','2025-10-14 02:17:16');
