INSERT INTO doctors VALUES(4,'dr. Shinta Pangestu, Sp.OG','dr-shinta-pangestu-spog',5,NULL,'{"en":{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"dr. Shinta Pangestu, Sp.OG, is a specialist in obstetrics and gynecology who currently serves patients at Altius Hospitals Harapan Indah. Dr. Shinta is dedicated to providing health services related to obstetrics and gynecology. She completed her education in obstetrics and gynecology at the University of Indonesia. She is also currently a member of the Indonesian Obstetrics and Gynecology Association (POGI)."}]}]},"id":"<p>dr. Shinta Pangestu, Sp.OG, adalah seorang spesialis obstetri dan ginekologi yang saat ini melayani pasien di Rumah Sakit Altius Harapan Indah. Dr. Shinta berkomitmen untuk memberikan layanan kesehatan yang berkaitan dengan obstetri dan ginekologi. Ia menyelesaikan pendidikan spesialisnya di bidang obstetri dan ginekologi di Universitas Indonesia. Saat ini, ia juga merupakan anggota dari Perhimpunan Obstetri dan Ginekologi Indonesia (POGI).</p>"}','{"en":{"type":"doc","content":[{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"2D, 3D, 4D, and transvaginal ultrasounds"}]}]},{"type":"listItem","attrs":{"style":"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shado