INSERT INTO doctors VALUES(5,'dr. Ivan Noersyid, Sp.JP','dr-ivan-noersyid-spjp',28,NULL,'{"en":"<p>dr. Ivan Noersyid, SpJp is a cardiologist dedicated to providing consultation services for heart and blood vessel health.</p><p>He is a member of the Indonesian Medical Association (IDI) and the Indonesian Cardiovascular Specialist Association (PERKI).</p>","id":"<p>Dr. Ivan Noersyid, SpJp adalah seorang kardiolog yang berdedikasi dalam memberikan layanan konsultasi untuk kesehatan jantung dan pembuluh darah.</p><p>Beliau merupakan anggota Ikatan Dokter Indonesia (IDI) dan Perhimpunan Ahli Jantung dan Pembuluh Darah Indonesia (PERKI).</p>"}','{"en":"<ul><li><p>General Cardiologist</p><p>Transthoracic Echo, Doppler Vascular Ultrasound, Stress</p><p>Treadmill/Dobutamine Echo, Holter ECG, Clinical Examination and ECG.</p></li></ul>","id":"<ul><li><p>Dokter Spesialis Jantung Umum.</p><p>Ekokardiografi Transthoracic, Ultrasonografi Vaskular Doppler, Uji Treadmill Stres/Ekokardiografi Dobutamine, Holter EKG, Pemeriksaan Klinis, dan EKG.</p></li></ul>"}','{"en":"<ul><li><p>Bachelor&#039;s degree from the University of Indonesia, general medicine.</p></li><li><p>Specialist education at the Faculty of Cardiology and Vascular Medicine, University of Indonesia.</p></li></ul>","id":"<ul><li><p>Sarjana Kedokteran Umum dari Universitas Indonesia.</p></li><li><p>Pendidikan spesialis di Fakultas Kardiologi dan Kedokteran Vaskular, Universitas Indonesia.</p></li></ul>"}','{"en":"<ol start=\"1\"><li><p>Dr. Arya, M.D., et al. &quot;The Effectiveness of Physical Therapy in the Management of Chronic Low Back Pain.&quot; Journal of Orthopedic and Trauma, vol. 15, no. 2, 2023, pp. 123-134.</p></li><li style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-posit