INSERT INTO doctors VALUES(8,'dr. Juan Gunawan, Sp.OG','dr-juan-gunawan-spog',5,'11','{"en":{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"dr. Juan Gunawan, Sp.OG is an Obstetrician and Gynecologist currently practicing at Altius Hospitals Harapan Indah. He completed his specialist education at Hasanuddin University, Makassar. With clinical experience since 2013."}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; --tw-contain-size: ; --tw-contain-layout: ; --tw-contain-paint: ; --tw-contain-style: ; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(82, 82, 82); margin: 0px; font-size: 20px; color: rgb(82, 82, 82); font-family: \"Overused Grotesk\", sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"dr. Juan is also active in scientific publications and participates in various training programs to enhance his expertise. Known for his professionalism and dedication, dr. Juan prioritizes providing the best possible care for each of his patients."}]}]},"id":"<p>dr. Juan Gunawan, Sp.OG adalah seorang Dokter Spesialis Obstetri dan Ginekologi yang saat ini praktik di Rumah Sakit Altius Harapan Indah. Ia menyelesaikan pendidikan spesialisnya di Universitas Hasanuddin, Makassar. Dengan pengalaman klinis sejak tahun 2013.</p><p>dr. Juan juga aktif dalam publikasi ilmiah dan mengikuti berbagai program pelatihan untuk meningkatkan keahliannya. Dikenal karena profesionalisme dan dedikasinya, dr. Juan memprioritaskan memberikan perawatan terbaik bagi setiap pasiennya.</p>"}','{"en":{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"-"}]}]},"id":"<p>-</p>"}','{"en":{"type":"doc","content":[{"type":"orderedList","attrs":{"style":"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contr