aturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; --tw-contain-size: ; --tw-contain-layout: ; --tw-contain-paint: ; --tw-contain-style: ; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(82, 82, 82);"},"content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Dr. Arya, M.D., et al. \"Genetic Factors in the Development of Osteoarthritis.\" Journal of Genetic Medicine, vol. 18, no. 1, 2021, pp. 98-109."}]}]}]}]},"id":"<ol start=\"1\"><li><p>Dr. Arya, M.D., dkk. “Efektivitas Terapi Fisik dalam Pengelolaan Nyeri Punggung Bawah Kronis.” Jurnal Ortopedi dan Trauma, vol. 15, no. 2, 2023, hlm. 123-134.</p></li><li><p>Dr. Arya, M.D., dkk. “Hasil Pengobatan Bedah pada Fraktur Kompleks Tulang Paha.” Jurnal Bedah Ortopedi, vol. 22, no. 4, 2022, hlm. 567-578.</p></li><li><p>Dr. Arya, M.D., dkk. “Faktor Genetik dalam Pengembangan Osteoartritis.” Jurnal Kedokteran Genetika, vol. 18, no. 1, 2021, hlm. 98-109.</p></li></ol>"}','2025-10-15 01:59:38','2025-10-15 02:01:45');
INSERT INTO doctors VALUES(9,'Dr. dr. Tri Wisesa Soetisna, Sp.B, Sp.BTKV, Subsp.JD(K), MARS','dr-dr-tri-wisesa-soetisna-spb-spbtkv-subspjdk-mars',31,NULL,'{"en":"<p>dr. Tri Wisesa Soetisna, Sp.BTKV(K), MARS is a Specialist Surgeon with a subspecialty in Cardiovascular Thoracic Surgery who specializes in heart, lung, esophagus, and other chest organ surgeries with over 24 years of experience. He completed his education in Thoracic and Cardiovascular Surgery at the University of Indonesia in 1993.</p><p>Currently, dr. Tri Wisesa Soetisna, Sp.BTKV(K), MARS practices at Altius Hospital Harapan Indah Bekasi as a Thoracic and Cardiovascular Surgeon. dr. Tri Wisesa Soetisna, Sp.BTKV(K), MARS is a member of the Indonesian Association of Thoracic, Cardiac, and Vascular Surgeons (HBTKVI), the Indonesian Medical Association (IDI), and the Indonesian Association of Surgeons (IKABI). The healthcare services provided by him include: Thoracic and Cardiovascular Surgery, Heart Surgery.</p>","id":{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"dr. Tri Wisesa Soetisna, Sp.BTKV(K), MARS adalah seorang Ahli Bedah dengan subspesialisasi Bedah Kardiootoraks yang mengkhususkan diri dalam bedah jantung, paru-paru, esofagus, dan organ dada lainnya dengan pengalaman lebih dari 24 tahun. Ia menyelesaikan pendidikan dalam bidang Bedah Kardiootoraks di Universitas Indonesia pada tahun 1993."}]},{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Saat ini, dr. Tri Wisesa Soetisna, Sp.BTKV(K), MARS berpraktik di Rumah Sakit Altius Harapan Indah Bekasi sebagai Ahli Bedah Toraks dan Kardiovaskular. dr. Tri Wisesa Soetisna, Sp.BTKV(K), MARS merupakan anggota Asosiasi Bedah Toraks, Jantung, dan Vaskular Indonesia (HBTKVI), Ikatan Dokter Indonesia (IDI), dan Ikatan Karier Bedah Indonesia (IKABI). Layanan kesehatan yang disediakannya meliputi: Bedah Toraks dan Kardiovaskular, Bedah Jantung."}]}]}}','{"en":"<ul><li><p>Thoracic Surgery (lung and mediastinal diseases, thoracic trauma)</p></li><li><p>Adult Cardiac Surgery (Coronary Artery Bypass Grafting/CABG, Heart Valve Surgery, Adult Congenital Heart Surgery)</p></li><li><p>Aortic and Peripheral Vascular Disorders</p></li></ul>","id":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Bedah Toraks (penyakit paru-paru dan mediastinum, trauma toraks)"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Bedah Jantung pada Dewasa (Pembedahan Bypass Arteri Koroner/CABG, Pembedahan Katup Jantung, Pembedahan Jantung Kongenital pada Dewasa)"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Gangguan Pembuluh Darah Aorta dan Perifer"}]}]}]}]}}','{"en":"<ul><li><p>Faculty of Medicine, Padjadjaran University 1985</p></li><li><p>Faculty of Medicine, University of Indonesia Specialist Doctor Education Program in Surgery (Sp.B) 1993</p></li><li><p>Faculty of Medicine, University of Indonesia Specialist Study Program in Thoracic, Cardiac and Vascular Surgery 1998</p></li><li><p>Faculty of Medicine, University of Indonesia Study Program in Hospital Administration Studies (MARS) 2013</p></li><li><p>Faculty of Medicine, University of Indonesia, Doctoral Program in Medical Sciences 2019</p></li></ul>","id":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Fakultas Kedokteran, Universitas Padjadjaran 1985"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Fakultas Kedokteran, Universitas Indonesia Program Pendidikan Dokter Spesialis Bedah (Sp.B) 1993"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Fakultas Kedokteran, Universitas Indonesia Program Studi Spesialis Bedah Toraks, Jantung, dan Pembuluh Darah 1998"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Fakultas Kedokteran, Universitas Indonesia Program Studi Administrasi Rumah Sakit (MARS) 2013"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Fakultas Kedokteran, Universitas Indonesia, Program Doktor Ilmu Kedokteran 2019"}]}]}]}]}}','{"en":"<ol start=\"1\"><li><p>Dr. Arya, M.D., et al. &quot;The Effectiveness of Physical Therapy in the Management of Chronic Low Back Pain.&quot; Journal of Orthopedic and Trauma, vol. 15, no. 2, 2023, pp. 123-134.</p></li><li style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; --tw-contain-size: ; --tw-