INSERT INTO offers VALUES(3,'{"en":"Eye Health Screening Package","id":"Paket Skrining Kesehatan Mata"}','{"en":"eye-health-screening-package","id":"paket-skrining-kesehatan-mata"}','18','{"en":{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"See the World Clearly with Altius Hospitals"}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Good vision is crucial for your daily life. Our Eye Health Screening Package is designed to detect vision problems, cataracts, or glaucoma at an early stage."}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Early detection can prevent further damage and maintain long-term eye health."}]},{"type":"heading","attrs":{"level":3,"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Package Includes:"}]},{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Consultation with an ophthalmologist"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Visual acuity test to measure eyesight sharpness"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Tonometry (eye pressure test) to detect glaucoma risk"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Slit lamp examination for detailed eye structure evaluation"}]}]}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Price starts from "},{"type":"text","text":"IDR 750,000","marks":[{"type":"bold"}]},{"type":"text","text":". With the latest diagnostic equipment and skilled specialists, we are committed to providing the best care for your eyes."}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Your Vision, Our Care – because clear sight means a brighter life.","marks":[{"type":"bold"}]}]}]},"id":"<h2 style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Lihat Dunia dengan Jelas bersama Rumah Sakit Altius</h2><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Penglihatan yang baik sangat penting untuk kehidupan sehari-hari Anda. Paket Pemeriksaan Kesehatan Mata kami dirancang untuk mendeteksi masalah penglihatan, katarak, atau glaukoma pada tahap awal.</p><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Deteksi dini dapat mencegah kerusakan lebih lanjut dan menjaga kesehatan mata jangka panjang.</p><h3 style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Paket Termasuk:</h3><ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p>Konsultasi dengan ahli mata</p></li><li><p>Tes ketajaman visual untuk mengukur kejernihan penglihatan</p></li><li><p>Tonometri (tes tekanan mata) untuk mendeteksi risiko glaukoma</p></li><li><p>Pemeriksaan lampu kipas untuk evaluasi struktur mata secara rinci</p></li></ul><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Harg mulai dari <strong>IDR 750,000</strong>. Dengan peralatan diagnostik terbaru dan spesialis yang ahli, kami berkomitmen untuk memberikan perawatan terbaik untuk mata Anda.</p><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><strong>Visi Anda, Perawatan Kami – karena penglihatan yang jelas berarti kehidupan yang lebih cerah.</strong></p>"}',1,'2025-10-17 02:00:19','2025-10-17 02:07:28');
INSERT INTO offers VALUES(4,'{"en":"Special Offers!","id":"Penawaran Spesial!"}','{"en":"special-offers","id":"penawaran-spesial"}','18','{"en":{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Safer & More Comfortable Heart Stent Implantation Package Price 75 Million – Angioplasty PCI"}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"What is included in this package?","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"type":"text","text":"1. One heart stent"},{"type":"hardBreak"},{"type":"text","text":"2. 2-day, 1-night hospital stay"},{"type":"hardBreak"},{"type":"text","text":"3. Doctor''s services & procedures"},{"type":"hardBreak"},{"type":"text","text":"4. Medications & medical equipment"},{"type":"hardBreak"},{"type":"text","text":"5. Laboratory tests, diagnostics & radiology"}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Cath Lab Promotion Terms and Conditions","marks":[{"type":"bold"}]},{"type":"text","text":":"},{"type":"hardBreak"},{"type":"text","text":"1. Procedures and consultations are performed by Dr. Julio Ulaan, "},{"type":"text","text":"B.Med.Sc","marks":[{"type":"link","attrs":{"href":"http://B.Med.Sc"}}]},{"type":"text","text":", SpJP (K), FIHA"},{"type":"hardBreak"},{"type":"text","text":"2. The procedure to be performed is determined based on prior consultation with the doctor."},{"type":"hardBreak"},{"type":"text","text":"3. Rates are valid until the end of December 2025."},{"type":"hardBreak"},{"type":"text","text":"4. Rates do not apply in the event of complications."},{"type":"hardBreak"},{"type":"text","text":"5. Includes inpatient administration fees."}]}]},"id":"<h2 style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Paket Implantasi Stent Jantung yang Lebih Aman dan Nyaman Harga 75 Juta – Angioplasti PCI</h2><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><strong>Apa saja yang termasuk dalam paket ini?</strong><br>1. Satu stent jantung<br>2. Menginap di rumah sakit selama 2 hari dan 1 malam<br>3. Layanan dokter dan prosedur medis<br>4. Obat-obatan dan peralatan medis<br>5. Tes laboratorium, diagnostik, dan radiologi</p><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><strong>Syarat dan Ketentuan Promosi Cath Lab:</strong><br>1.  Prosedur dan konsultasi dilakukan oleh Dr. Julio Ulaan, <a href=\"http://B.Med.Sc\">B.Med.Sc</a>, SpJP (K), FIHA<br>2. Prosedur yang akan dilakukan ditentukan berdasarkan konsultasi sebelumnya dengan dokter.<br>3. Tarif berlaku hingga akhir Desember 2025.<br>4. Tarif tidak berlaku jika terjadi komplikasi.<br>5. Termasuk biaya administrasi rawat inap.</p>"}',1,'2025-10-17 02:01:12','2025-10-17 02:06:17');
INSERT INTO offers VALUES(5,'{"en":"Promo Orthopedic, Total Knee Replacement!","id":"Promo Bedah Orthopedi, Penggantian Sendi Lutut Total!"}','{"en":"promo-orthopedic-total-knee-replacement","id":"promo-bedah-orthopedi-penggantian-sendi-lutut-total"}','18','{"en":{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Regain Your Freedom of Movement with Altius Hospitals Bekasi!","marks":[{"type":"bold"}]}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Knee pain caused by arthritis, injury, or bone degeneration often hinders daily activities. Even simple movements such as walking, climbing stairs, or simply standing can be extremely painful. Now, Altius Hospitals Bekasi is here to help you regain your freedom of movement through the "},{"type":"text","text":"Total Knee Replacement Promotion","marks":[{"type":"bold"}]},{"type":"text","text":" with "},{"type":"text","text":"special prices and the best service","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Total Knee Replacement is a modern medical procedure that replaces a damaged knee joint with a high-quality artificial joint (prosthesis). This procedure is proven to be safe and effective in reducing pain, improving knee function, and enhancing the patient''s quality of life."}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"At Altius Hospitals Bekasi, you will be treated by a team of experienced "},{"type":"text","text":"orthopedic specialists","marks":[{"type":"link","attrs":{"href":"https://fiddle.jshell.net/%22https://altiushospitals.id//%22"}}]},{"type":"text","text":" supported by the latest medical technology! With a patient-centered care approach, we ensure that every patient receives comprehensive consultation, personalized care, and post-operative recovery assistance."}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Through this special promotion, we want more people to experience the real benefits of Total Knee Replacement without having to worry too much about the cost. Now is the time to reduce pain, regain independence, and enjoy precious moments with your beloved family again. Don''t let knee pain limit your mobility. Take advantage of the "},{"type":"text","text":"Total Knee Replacement Promotion at Altius Hospitals Bekasi","marks":[{"type":"bold"}]},{"type":"text","text":" today. Consult now and start your journey towards a healthier, more active, and energetic life."}]}]},"id":"<h2 style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><strong>Kembalikan Kebebasan Gerak Anda dengan Altius Hospitals Bekasi!</strong></h2><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Nyeri lutut akibat arthritis, cedera, atau degenerasi tulang seringkali menghalangi aktivitas sehari-hari. Bahkan gerakan sederhana seperti berjalan, menaiki tangga, atau sekadar berdiri pun bisa sangat menyakitkan. Kini, Altius Hospitals Bekasi hadir untuk membantu Anda mengembalikan kebebasan gerak melalui <strong>Program Penggantian Lutut Total</strong> dengan <strong>harga spesial dan layanan terbaik.</strong></p><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Penggantian Sendi Lutut Total adalah prosedur medis modern yang mengganti sendi lutut yang rusak dengan sendi buatan berkualitas tinggi (prostesis). Prosedur ini terbukti aman dan efektif dalam mengurangi nyeri, meningkatkan fungsi lutut, dan meningkatkan kualitas hidup pasien.</p><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Di Altius Hospitals Bekasi, Anda akan ditangani oleh tim spesialis ortopedi berpengalaman yang didukung oleh teknologi medis terbaru! Dengan pendekatan perawatan yang berpusat pada pasien, kami memastikan setiap pasien mendapatkan konsultasi komprehensif, perawatan yang disesuaikan, dan bantuan pemulihan pasca operasi.</p><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Melalui promosi khusus ini, kami ingin lebih banyak orang merasakan manfaat nyata dari Total Knee Replacement tanpa harus terlalu khawatir tentang biayanya. Sekaranglah saatnya untuk mengurangi nyeri, mendapatkan kembali kemandirian, dan menikmati momen berharga bersama keluarga tercinta Anda kembali. Jangan biarkan nyeri lutut membatasi mobilitas Anda. Manfaatkan <strong>Promosi Total Knee Replacement di Altius Hospitals Bekasi</strong> hari ini. Konsultasikan sekarang dan mulailah perjalanan Anda menuju kehidupan yang lebih sehat, aktif, dan berenergi.</p>"}',1,'2025-10-17 02:09:16','2025-10-17 02:12:50');
INSERT INTO offers VALUES(6,'{"en":"Child Growth & Development Screening","id":"Skrining Pertumbuhan & Perkembangan Anak"}','{"en":"child-growth-development-screening","id":"skrining-pertumbuhan-perkembangan-anak"}','18','{"en":{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Monitor Your Child’s Growth with Altius Hospitals"}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Children grow rapidly, and monitoring their growth and development is crucial to ensure they reach their full potential. Our screening package provides a complete assessment of your child’s health."}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Our pediatric specialists will carefully evaluate your child’s physical growth and developmental milestones, giving you peace of mind as a parent."}]},{"type":"heading","attrs":{"level":3,"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"What’s Inside?"}]},{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Comprehensive pediatric consultation"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Height, weight, and BMI assessment"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Nutritional evaluation and personalized advice"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Developmental milestone check"}]}]}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"This package is highly recommended for children under 12 years old. Special promotional rate: "},{"type":"text","text":"IDR 500,000","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Early check-up for a brighter future – because every child deserves the best start in life.","marks":[{"type":"bold"}]}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"(021) 3000 – 8877","marks":[{"type":"link","attrs":{"href":"https://altiushospitals.id/kontak/"}}]}]}]},"id":"<h2 style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Pantau Pertumbuhan Anak Anda dengan Rumah Sakit Altius</h2><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Anak-anak tumbuh dengan cepat, dan memantau pertumbuhan serta perkembangan mereka sangat penting untuk memastikan mereka mencapai potensi penuh. Paket skrining kami menyediakan penilaian lengkap terhadap kesehatan anak Anda.</p><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Spesialis pediatrik kami akan dengan cermat mengevaluasi pertumbuhan fisik dan tonggak perkembangan anak Anda, memberi Anda ketenangan pikiran sebagai orang tua.</p><h3 style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Apa Isinya?</h3><ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p>Konsultasi pediatrik komprehensif</p></li><li><p>Penialian tinggi badan, berat badan, dan BMI</p></li><li><p>Evaluasi gizi dan saran pribadi</p></li><li><p>Pemeriksaan tonggaak perkembangan</p></li></ul><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Paket ini sangat direkomendasikan untuk anak-anak di bawah 12 tahun. Tarif promosi khusus: <strong>IDR 500,000</strong>.</p><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><strong>Pemeriksaan dini untuk masa depan yang lebih cerah – karena setiap anak berhak mendapatkan awal terbaik dalam hidup.</strong></p><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><a href=\"https://altiushospitals.id/kontak/\">(021) 3000 – 8877</a></p>"}',1,'2025-10-17 02:09:24','2025-10-17 02:15:37');
INSERT INTO offers VALUES(7,'{"en":"Get to know Altius Hospitals Physiotherapy!","id":"Kenalan dengan Fisioterapi Altius Hospitals!"}','{"en":"get-to-know-altius-hospitals-physiotherapy","id":"kenalan-dengan-fisioterapi-altius-hospitals"}','18','{"en":"<h3 style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">It&#039;s Time to Move On from Pain! Get to Know Altius Hospitals Physiotherapy</h3><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Combined with advanced technology, Altius Hospitals physiotherapy services are undoubtedly the best in their field. The physiotherapy equipment and services available are also equally impressive:</p><ul style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><li><p><strong>SIS (Super Inductive System)</strong>: therapy using electromagnetic waves to stimulate muscles, joints, and nerves, thereby helping to reduce pain and joint stiffness.</p></li><li><p><strong>FSWT (Focused Shock Wave Therapy)</strong>: therapy for chronic conditions and deeper injuries, such as piriformis syndrome, plantar fasciitis, and calcification of the knees and waist.</p></li><li><p><strong>Spinal Decompression</strong>: helps treat pinched nerves in the neck and waist, as well as scoliosis.</p></li><li><p><strong>Emsella Treatment</strong>: strengthens weakened pelvic floor muscles, beneficial for urinary incontinence, sexual dysfunction, and improved bladder control.</p></li><li><p><strong>Gym Physio</strong>: specialized physical exercises to maximize recovery through targeted exercise.</p></li></ul><p style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">So, what are you waiting for? Try Altius Hospitals&#039; physiotherapy services now and feel the difference!</p>","id":{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Saatnya Melupakan Rasa Sakit! Kenali Layanan Fisioterapi Rumah Sakit Altius"}]},{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Dengan menggabungkan teknologi canggih, layanan fisioterapi Rumah Sakit Altius tanpa diragukan lagi merupakan yang terbaik di bidangnya. Peralatan dan layanan fisioterapi yang tersedia juga sama mengesankannya:"}]},{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"SIS (Super Inductive System): terapi menggunakan gelombang elektromagnetik untuk merangsang otot, sendi, dan saraf, sehingga membantu mengurangi rasa sakit dan kekakuan sendi."}]},{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"FSWT (Focused Shock Wave Therapy): terapi untuk kondisi kronis dan cedera yang lebih dalam, seperti sindrom piriformis, plantar fasciitis, dan pengerasan sendi lutut dan pinggang."}]},{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Spinal Decompression: membantu mengobati saraf terjepit di leher dan pinggang, serta skoliosis."}]},{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Emsella Treatment: menguatkan otot dasar panggul yang melemah, bermanfaat untuk inkontinensia urin, disfungsi seksual, dan peningkatan kontrol kandung kemih."}]},{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Gym Physio: latihan fisik khusus untuk memaksimalkan pemulihan melalui latihan yang ditargetkan."}]},{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Jadi, apa yang Anda tunggu? Coba layanan fisioterapi Altius Hospitals sekarang dan rasakan perbedaannya!"}]},{"type":"paragraph","attrs":{"textAlign":"start","class":null,"style":null},"content":[{"type":"text","text":"Translated with"}]}]}}',1,'2025-10-17 02:10:36','2025-10-17 02:12:55');
