"}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"8. Stroke Screening"}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"9. Heart & Stroke (H&S) Screening"}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"10. Premarital Package"}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"11. Household Assistant Screening"}]},{"type":"heading","attrs":{"level":3,"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"Terms and Conditions for Angpao and Lantern Packages","marks":[{"type":"bold"}]}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"1. Medical check-ups are conducted every Monday to Friday"}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"2. Examinations and consultations are not tied to a specific doctor (according to the on-call schedule)."}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"3. Examinations and consultations must be conducted on the same day."}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"4. Medical Check-Up Preparation:"}]},{"type":"bulletList","attrs":{"style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Patients must fast for 8-10 hours before the examination (no food) and are only allowed to drink water"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Women must not be menstruating"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"No smoking, consuming alcoholic beverages, or taking medication before the examination (while fasting)"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"For lab test results, hard copies will be submitted within 24 hours on working days, and MCU reports within 48 hours on working days."}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":"start"},"content":[{"type":"text","text":"Patients are required to make an"},{"type":"text","text":"appointment","marks":[{"type":"bold"}]},{"type":"text","text":" in advance"}]}]}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"5. Meals depend on the package chosen"}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"6. Medical Check-Up examinations cannot be conducted on red dates or public holidays"}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"},"content":[{"type":"text","text":"7. The 2025 rates are subject to change at any time and will be communicated if there are price changes"}]}]},"id":"<p>Paket Pemeriksaan Kesehatan Altius Telah Diperbarui!</p><p>Temukan promosi pemeriksaan kesehatan terbaru dari Rumah Sakit Altius, yang disesuaikan khusus dengan kebutuhan Anda!</p><p>Paket MCU</p><p>1. MCU Umum – Bronze</p><p>2. MCU Umum – Silver</p><p>3. MCU Umum – Platinum</p><p>4. MCU Umum – Diamond</p><p>5. MCU Kardiovaskular – Silver</p><p>6. MCU Kardiovaskular – Gold</p><p>7. MCU Kardiovaskular – Diamond</p><p>8. Skrining Stroke</p><p>9. Skrining Jantung &amp; Stroke (H&amp;S)</p><p>10. Paket Pra-Nikah</p><p>11. Skrining Asisten Rumah Tangga</p><p>Syarat dan Ketentuan untuk Paket Angpao dan Lentera</p><p>1. Pemeriksaan kesehatan dilakukan setiap Senin hingga Jumat</p><p>2. Pemeriksaan dan konsultasi tidak terikat pada dokter tertentu (sesuai jadwal piket).</p><p>3. Pemeriksaan dan konsultasi harus dilakukan pada hari yang sama.</p><p>4. Persiapan Pemeriksaan Kesehatan:</p><p>Pasien harus berpuasa selama 8-10 jam sebelum pemeriksaan (tidak makan) dan hanya boleh minum air</p><p>Wanita tidak boleh sedang menstruasi</p><p>Tidak boleh merokok, mengonsumsi minuman beralkohol, atau mengonsumsi obat-obatan sebelum pemeriksaan (selama berpuasa)</p><p>Untuk hasil tes laboratorium, salinan cetak akan diserahkan dalam 24 jam pada hari kerja, dan laporan MCU dalam 48 jam pada hari kerja.</p><p>Pasien diharuskan membuat janji temu terlebih dahulu</p><p>5. Makanan tergantung pada paket yang dipilih</p><p>6. Pemeriksaan kesehatan tidak dapat dilakukan pada hari merah atau hari libur nasional</p><p>7. Tarif 2025 dapat berubah sewaktu-waktu dan akan diinformasikan jika ada perubahan harga</p>"}',1,'2025-10-17 02:16:16','2025-10-17 02:18:15');
INSERT INTO offers VALUES(9,'{"en":"Exclusive Dental Check-Up Promo","id":"Promo Pemeriksaan Gigi Eksklusif"}','{"en":"exclusive-dental-check-up-promo","id":"promo-pemeriksaan-gigi-eksklusif"}','18','{"en":{"type":"doc","content":[{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;","class":null,"id":null},"content":[{"type":"text","text":"Healthy Smile, Healthy Life!"}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;","class":null},"content":[{"type":"text","text":"Your dental health is an essential part of your overall well-being. At Altius Hospitals, we provide comprehensive dental check-up services with advanced technology and experienced dentists."}]},{"type":"paragraph","attrs":{"textAlign":"start","style":"color: rgb(0, 0, 0); font-family: \"Times New Roman\"; font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-