INSERT INTO settings VALUES(6,'privacy_policy','{"content_en":"<p>Altius Hospitals respects the privacy of website users and is committed to protecting it seriously. This Privacy Policy is designed to help Users understand how Altius Hospitals and\/or our subsidiaries collect, use, share, and protect information while respecting Users&#039; rights in using the <a href=\"http:\/\/altiushospitals.id\">altiushospitals.id<\/a> website.<\/p><p>The use of Altius Hospitals&#039; Services and any personal information provided by users must always comply with the terms and conditions of this Privacy Policy.<\/p>","content_id":"<p>Altius Hospitals menghormati privasi pengguna website dan berkomitmen untuk menjaganya dengan serius. Kebijakan Privasi ini dibuat untuk membantu Pengguna agar mengetahui bagaimana cara Altius Hospitals dan\/atau anak perusahaan kami dalam mengumpulkan, menggunakan, membagikan, dan melindungi informasi dengan tetap menghormati Hak Pengguna dalam menggunakan situs <a href=\"http:\/\/altiushospitals.id\">altiushospitals.id<\/a><\/p><p>Penggunaan atas Layanan Altius Hospitals beserta setiap informasi pribadi yang diberikan oleh Pengguna, harus senantiasa tunduk pada syarat dan ketentuan Kebijakan Privasi.<\/p>","faq":[{"title_en":null,"content_en":null,"title_id":null,"content_id":null}]}','2025-10-24 06:33:28','2025-10-24 06:35:07');
